SELECT COUNT(*) tickets,SUM(response_eligible) response_eligible,SUM(response_breach) response_breaches,1.0-SUM(response_breach)*1.0/SUM(response_eligible) response_attainment,SUM(resolution_eligible) resolution_eligible,1.0-SUM(resolution_breach)*1.0/SUM(resolution_eligible) resolution_attainment,SUM(open_flag) open_tickets,SUM(overdue_open) overdue_open,SUM(csat_responded) survey_responses,1.0*SUM(csat_positive)/SUM(csat_responded) csat_positive FROM tickets
